package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeField(field string) string {
	// Only allow alphanumeric and underscore in field names
	for _, c := range field {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			return "name"
		}
	}
	return field
}

func buildSearchQuery(req SearchRequest) string {
	fields := "id, name, price, sku"
	if len(req.Fields) > 0 {
		sanitized := make([]string, 0, len(req.Fields))
		for _, f := range req.Fields {
			sanitized = append(sanitized, sanitizeField(f))
		}
		fields = strings.Join(sanitized, ", ")
	}

	// Build WHERE clause - uses ILIKE for search
	where := fmt.Sprintf("WHERE name ILIKE '%%%s%%' OR sku ILIKE '%%%s%%'", req.Query, req.Query)

	orderBy := "id"
	if req.OrderBy != "" {
		orderBy = sanitizeField(req.OrderBy)
	}

	limit := 50
	if req.Limit > 0 && req.Limit <= 200 {
		limit = req.Limit
	}

	return fmt.Sprintf("SELECT %s FROM products %s ORDER BY %s LIMIT %d", fields, where, orderBy, limit)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	if len(req.Query) > 500 {
		http.Error(w, "Query too long", 400)
		return
	}

	query := buildSearchQuery(req)
	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
